import { useEffect, useRef, useState } from 'react'
import gallery from '../../data/gallery.json'
import { IconChevronLeft, IconChevronRight, IconClose } from '../components/Icons'
import { asset, step } from '../lib'
import { useI18n } from '../locale/i18n'

// data/gallery.json is generated by scripts/generate-gallery.mjs. alt/caption can be edited by hand.
interface Photo {
  file: string
  src: string
  alt?: string
  caption?: string
  width?: number
  height?: number
}

export default function Gallery() {
  const { t } = useI18n()
  const photos = gallery as Photo[]
  const [open, setOpen] = useState<number | null>(null)
  const closeBtn = useRef<HTMLButtonElement>(null)
  const opener = useRef<HTMLElement | null>(null)
  const startX = useRef<number | null>(null)

  const label = (ph: Photo) => ph.alt || ph.caption || ph.file
  const move = (dir: 1 | -1) =>
    setOpen((cur) => (cur === null ? cur : (cur + dir + photos.length) % photos.length))
  const close = () => {
    setOpen(null)
    opener.current?.focus()
  }

  // Lightbox: Escape / arrow keys, page scroll locked while open.
  useEffect(() => {
    if (open === null) return
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') close()
      if (e.key === 'ArrowLeft') move(-1)
      if (e.key === 'ArrowRight') move(1)
    }
    document.addEventListener('keydown', onKey)
    document.documentElement.style.overflow = 'hidden'
    closeBtn.current?.focus()
    return () => {
      document.removeEventListener('keydown', onKey)
      document.documentElement.style.overflow = ''
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open === null])

  const current = open !== null ? photos[open] : null

  return (
    <section id="gallery" className="section bg-alt" aria-labelledby="gallery-title">
      <div className="wrap">
        <div className="reveal">
          <h2 id="gallery-title" className="section-title">
            {t('gallery.title')}
          </h2>
          <span className="title-bar" />
          <p className="section-sub">{t('gallery.subtitle')}</p>
        </div>

        {photos.length === 0 ? (
          <p className="reveal mt-8 text-muted">{t('gallery.empty')}</p>
        ) : (
          // CSS columns = masonry: every photo keeps its own aspect ratio
          <ul className="mt-10 columns-2 gap-3 md:columns-3 md:gap-4 xl:columns-4">
            {photos.map((ph, k) => (
              <li key={ph.file} className="reveal mb-3 break-inside-avoid md:mb-4" style={step(Math.min(k, 6))}>
                <button
                  type="button"
                  aria-label={t('gallery.open', { label: label(ph) })}
                  onClick={(e) => {
                    opener.current = e.currentTarget
                    setOpen(k)
                  }}
                  className="group block w-full cursor-zoom-in overflow-hidden rounded-xl border border-line bg-card shadow-card"
                >
                  <img
                    src={asset(ph.src)}
                    alt={label(ph)}
                    width={ph.width}
                    height={ph.height}
                    loading="lazy"
                    decoding="async"
                    style={ph.width && ph.height ? { aspectRatio: `${ph.width} / ${ph.height}` } : undefined}
                    className="block h-auto w-full transition-transform duration-300 group-hover:scale-[1.03]"
                  />
                </button>
              </li>
            ))}
          </ul>
        )}
      </div>

      {current && open !== null && (
        <div
          role="dialog"
          aria-modal="true"
          aria-label={t('gallery.lightbox')}
          className="fixed inset-0 z-50 flex flex-col bg-black/90 p-3 sm:p-6"
          onClick={close}
          onTouchStart={(e) => (startX.current = e.touches[0].clientX)}
          onTouchEnd={(e) => {
            if (startX.current === null) return
            const dx = e.changedTouches[0].clientX - startX.current
            startX.current = null
            if (Math.abs(dx) > 50) move(dx < 0 ? 1 : -1)
          }}
        >
          <div className="flex items-center justify-between text-white/80">
            <span className="text-sm tabular-nums">{t('gallery.count', { n: open + 1, total: photos.length })}</span>
            <button
              ref={closeBtn}
              type="button"
              className="icon-btn"
              aria-label={t('gallery.close')}
              onClick={(e) => {
                e.stopPropagation()
                close()
              }}
            >
              <IconClose />
            </button>
          </div>

          <div className="relative flex min-h-0 flex-1 items-center justify-center">
            <img
              src={asset(current.src)}
              alt={label(current)}
              onClick={(e) => e.stopPropagation()}
              className="max-h-full max-w-full rounded-lg object-contain"
            />
            {photos.length > 1 && (
              <>
                <button
                  type="button"
                  className="icon-btn absolute left-0 sm:left-2"
                  aria-label={t('gallery.prev')}
                  onClick={(e) => {
                    e.stopPropagation()
                    move(-1)
                  }}
                >
                  <IconChevronLeft />
                </button>
                <button
                  type="button"
                  className="icon-btn absolute right-0 sm:right-2"
                  aria-label={t('gallery.next')}
                  onClick={(e) => {
                    e.stopPropagation()
                    move(1)
                  }}
                >
                  <IconChevronRight />
                </button>
              </>
            )}
          </div>

          {current.caption && <p className="mt-3 text-center text-sm text-white/90">{current.caption}</p>}
        </div>
      )}
    </section>
  )
}
